import gzip
import json
import re
import datetime
import math
from csvtool import read_file, write_file

def read_csv(file_path):
    """Read CSV file, supporting gzip compression."""
    if file_path.endswith('.csv.gz'):
        with gzip.open(file_path, 'rt') as f:
            content = f.read()
    else:
        content = read_file(file_path)

    lines = content.splitlines()
    if not lines:
        raise ValueError("Empty file")

    first_line = lines[0]
    delimiter = ','
    if ';' in first_line:
        delimiter = ';'

    rows = [line.split(delimiter) for line in lines]
    headers = rows[0]
    data = rows[1:]

    return headers, data

def write_csv(file_path, headers, data):
    """Write CSV file, supporting gzip compression."""
    if file_path.endswith('.csv.gz'):
        with gzip.open(file_path, 'wt') as f:
